//! Menu icons from Google's Material Symbols (Rounded, weight 400),
//! https://github.com/google/material-design-icons, licensed under the
//! Apache License 2.0 (see licenses/material-symbols-LICENSE.txt).
//! SVG paths are pre-converted to move/line/cubic ops on a 24-unit grid and
//! filled with GDI paths on a supersampled surface, like the GitHub mark.
use std::ptr::null_mut;
use windows_sys::Win32::{Foundation::{POINT,RECT},Graphics::Gdi::*};

pub enum Op{M(f32,f32),L(f32,f32),C(f32,f32,f32,f32,f32,f32),Z}
use Op::*;

/// Fills `icon` into `rect` over whatever is already painted there.
pub unsafe fn paint(dc:HDC,rect:RECT,icon:&[Op],color:u32){
    const SCALE:i32=8;
    let width=rect.right-rect.left;let height=rect.bottom-rect.top;
    if width<=0||height<=0||RectVisible(dc,&rect)==0{return;}
    let size=width.min(height)*SCALE;
    let memory=crate::paint_cache::scratch(dc,size,size);
    if memory.is_null(){return;}
    SetStretchBltMode(memory,COLORONCOLOR);
    StretchBlt(memory,0,0,size,size,dc,rect.left,rect.top,width,height,SRCCOPY);
    let unit=size as f32/24.0;
    let point=|x:f32,y:f32|POINT{x:(x*unit).round()as i32,y:(y*unit).round()as i32};
    BeginPath(memory);
    for op in icon{
        match *op{
            M(x,y)=>{let p=point(x,y);MoveToEx(memory,p.x,p.y,null_mut());}
            L(x,y)=>{let p=point(x,y);LineTo(memory,p.x,p.y);}
            C(x1,y1,x2,y2,x,y)=>{let points=[point(x1,y1),point(x2,y2),point(x,y)];PolyBezierTo(memory,points.as_ptr(),3);}
            Z=>{CloseFigure(memory);}
        }
    }
    EndPath(memory);
    let old_mode=SetPolyFillMode(memory,WINDING);
    let old_brush=SelectObject(memory,crate::paint_cache::brush(color));
    FillPath(memory);
    SelectObject(memory,old_brush);SetPolyFillMode(memory,old_mode);
    let old_stretch=SetStretchBltMode(dc,HALFTONE);
    StretchBlt(dc,rect.left,rect.top,width,height,memory,0,0,size,size,SRCCOPY);
    SetStretchBltMode(dc,old_stretch);
}

